const menuButton=document.querySelector('.menu-button');const nav=document.querySelector('#main-nav');menuButton.addEventListener('click',()=>{const open=nav.classList.toggle('open');menuButton.setAttribute('aria-expanded',String(open))});nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{nav.classList.remove('open');menuButton.setAttribute('aria-expanded','false')}));document.querySelector('#booking-form').addEventListener('submit',event=>{event.preventDefault();event.currentTarget.querySelector('.form-status').textContent='Thank you. Your appointment request has been received.';event.currentTarget.reset()});
